       status, source, view, alt, url, remarks, seq)
JOIN series s          ON s.name = v.series
JOIN part_categories c ON c.name = v.category
ON CONFLICT (photo_id) DO NOTHING;

-- Link products that existed before this migration to the new reference tables
-- (matched on the existing brand-free text columns series / category).
UPDATE products p
SET series_id   = s.id,
    category_id = c.id,
    seq         = COALESCE(NULLIF(substring(p.photo_id from '-(\d+)$'), '')::int, 1)
FROM series s, part_categories c
WHERE p.series = s.name AND p.category = c.name
  AND (p.series_id IS NULL OR p.category_id IS NULL);

DO $$
DECLARE n INT;
BEGIN
  SELECT COUNT(*) INTO n FROM products WHERE series_id IS NULL OR category_id IS NULL;
  RAISE NOTICE 'Products not linked to a series/category: % (legacy rows that do not match the sheet)', n;
END $$;

COMMIT;
